def minMax(numbers):
    return min(numbers), max(numbers)

smallest, largest = minMax([4, 9, 1, 7])
print(smallest, largest)   # prints: 1 9

Writing several comma-separated values after 'return' makes Python automatically pack them into a single tuple, which the caller can then unpack into separate variables, as shown with smallest and largest.

def deleteChar(text, char):
    result = ''
    for ch in text:
        if ch != char:
            result = result + ch
    return result

print(deleteChar('banana', 'a'))   # prints: bnn

Since strings are immutable, a new string is built up character by character, skipping the character to be removed, and this new string is returned.

def countOccurrences(myList, element):
    total = 0
    for item in myList:
        if item == element:
            total = total + 1
    return total

nums = [2, 5, 2, 8, 2, 9]
print(countOccurrences(nums, 2))   # prints: 3
